-- TaxiRide database for Homa Bay. Import this file in phpMyAdmin (XAMPP) or run: mysql -u root < database.sql
CREATE DATABASE IF NOT EXISTS taxiride CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE taxiride;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS ticket_replies, tickets, notifications, saved_places, ratings, payments, booking_logs, bookings, promo_codes, fares, locations, vehicles, vehicle_types, drivers, password_resets, audit_log, settings, users;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY, role ENUM('customer','driver','admin') NOT NULL,
  name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, phone VARCHAR(20) NOT NULL,
  password VARCHAR(255) NOT NULL, status ENUM('active','suspended') NOT NULL DEFAULT 'active',
  last_login DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(role)
) ENGINE=InnoDB;
CREATE TABLE password_resets (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used TINYINT(1) NOT NULL DEFAULT 0,
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE drivers (user_id INT PRIMARY KEY, licence_no VARCHAR(40) NOT NULL, licence_expiry DATE NOT NULL, psv_badge VARCHAR(40), psv_expiry DATE NULL,
  availability ENUM('offline','available','busy') NOT NULL DEFAULT 'offline', base_area VARCHAR(80), joined_on DATE,
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE vehicle_types (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL, seats TINYINT NOT NULL, multiplier DECIMAL(3,2) NOT NULL DEFAULT 1.00) ENGINE=InnoDB;
CREATE TABLE vehicles (id INT AUTO_INCREMENT PRIMARY KEY, plate VARCHAR(15) NOT NULL UNIQUE, make VARCHAR(40), model VARCHAR(40), colour VARCHAR(30), year SMALLINT,
  vehicle_type_id INT NOT NULL, insurance_expiry DATE NOT NULL, inspection_expiry DATE NOT NULL, status ENUM('active','maintenance','retired') NOT NULL DEFAULT 'active', driver_id INT NULL,
  FOREIGN KEY(vehicle_type_id) REFERENCES vehicle_types(id), FOREIGN KEY(driver_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE locations (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, area ENUM('Town','Intertown','Intercounty') NOT NULL, landmark VARCHAR(120), active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE fares (id INT AUTO_INCREMENT PRIMARY KEY, from_location_id INT NOT NULL, to_location_id INT NOT NULL, amount INT NOT NULL, est_minutes SMALLINT NOT NULL DEFAULT 15,
  UNIQUE KEY pair (from_location_id, to_location_id), FOREIGN KEY(from_location_id) REFERENCES locations(id) ON DELETE CASCADE, FOREIGN KEY(to_location_id) REFERENCES locations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE promo_codes (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, type ENUM('percent','fixed') NOT NULL, value INT NOT NULL, min_fare INT NOT NULL DEFAULT 0,
  expires_on DATE NULL, max_uses INT NOT NULL DEFAULT 0, used_count INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE bookings (
  id INT AUTO_INCREMENT PRIMARY KEY, ref VARCHAR(20) NOT NULL UNIQUE, customer_id INT NULL, customer_name VARCHAR(100) NOT NULL, customer_phone VARCHAR(20) NOT NULL,
  trip_type ENUM('Town ride','Intertown','Intercounty','Hourly hire') NOT NULL, pickup_location_id INT NULL, dropoff_location_id INT NULL, pickup_detail VARCHAR(160), dropoff_detail VARCHAR(160),
  scheduled_at DATETIME NOT NULL, passengers TINYINT NOT NULL DEFAULT 1, vehicle_type_id INT NOT NULL, hours TINYINT NULL, notes VARCHAR(255),
  base_fare INT NOT NULL DEFAULT 0, discount INT NOT NULL DEFAULT 0, total_fare INT NOT NULL DEFAULT 0, promo_id INT NULL,
  status ENUM('pending','assigned','accepted','on_the_way','in_progress','completed','cancelled') NOT NULL DEFAULT 'pending',
  driver_id INT NULL, vehicle_id INT NULL, source ENUM('online','phone','whatsapp','stage') NOT NULL DEFAULT 'online',
  payment_method ENUM('cash','mpesa') NOT NULL DEFAULT 'cash', payment_status ENUM('unpaid','paid','verified') NOT NULL DEFAULT 'unpaid',
  cancel_reason VARCHAR(200), created_by INT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME NULL,
  INDEX(status), INDEX(driver_id), INDEX(customer_id), INDEX(scheduled_at),
  FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(driver_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL,
  FOREIGN KEY(vehicle_type_id) REFERENCES vehicle_types(id), FOREIGN KEY(pickup_location_id) REFERENCES locations(id) ON DELETE SET NULL, FOREIGN KEY(dropoff_location_id) REFERENCES locations(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE booking_logs (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, status VARCHAR(20) NOT NULL, note VARCHAR(255), user_id INT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX(booking_id), FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL, amount INT NOT NULL, method ENUM('cash','mpesa') NOT NULL, mpesa_code VARCHAR(15),
  status ENUM('recorded','verified','rejected') NOT NULL DEFAULT 'recorded', recorded_by INT NULL, recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, verified_by INT NULL, verified_at DATETIME NULL,
  FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE ratings (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT NOT NULL UNIQUE, customer_id INT NOT NULL, driver_id INT NOT NULL, stars TINYINT NOT NULL, comment VARCHAR(255),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE saved_places (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, label VARCHAR(40) NOT NULL, location_id INT NOT NULL, detail VARCHAR(160),
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(120) NOT NULL, message VARCHAR(300) NOT NULL, link VARCHAR(160),
  is_read TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id, is_read), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE tickets (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, booking_id INT NULL, category VARCHAR(30) NOT NULL, subject VARCHAR(120) NOT NULL,
  status ENUM('open','in_progress','resolved') NOT NULL DEFAULT 'open', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE ticket_replies (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT NOT NULL, user_id INT NOT NULL, message TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE audit_log (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(60) NOT NULL, detail VARCHAR(255), ip VARCHAR(45), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE settings (k VARCHAR(40) PRIMARY KEY, v VARCHAR(255) NOT NULL) ENGINE=InnoDB;


-- Sample data (dates are relative to the moment you import)












UPDATE drivers SET availability='busy' WHERE user_id IN (3,4,5); UPDATE drivers SET availability='offline' WHERE user_id IN (6,7);

UPDATE promo_codes p SET used_count=(SELECT COUNT(*) FROM bookings b WHERE b.promo_id=p.id);





